// =====================================
// Read & Clean Google Sheet Data
// =====================================

const rows = $input.all()
.map(item => ({
    date: String(item.json.date ?? "").trim(),
    category: String(item.json.category ?? "").trim(),
    brands: String(item.json.brands ?? "").trim(),
    qty_sold: Number(item.json.qty_sold ?? 0),
    net_sale: Number(item.json.net_sale ?? 0),
    gross_sale: Number(item.json.gross_sale ?? 0)
}))
.filter(r =>
    r.date !== "" &&
    r.brands !== ""
);

// =====================================
// Date Parser
// =====================================

function parseDate(str) {

    const months = {
        Jan:0, Feb:1, Mar:2, Apr:3,
        May:4, Jun:5, Jul:6, Aug:7,
        Sep:8, Oct:9, Nov:10, Dec:11
    };

    if (!str) return null;

    const parts = str.trim().split("-");

    if (parts.length !== 3) return null;

    const [day, month, year] = parts;

    return new Date(
        2000 + Number(year),
        months[month],
        Number(day)
    );

}

// =====================================
// Latest Date
// =====================================

const dates = [...new Set(rows.map(r => r.date))]
.filter(d => parseDate(d));

dates.sort((a,b)=>parseDate(a)-parseDate(b));

const latestDate = dates.at(-1);

// =====================================
// Yesterday Rows
// =====================================

const yesterdayRows = rows.filter(r =>
    r.date === latestDate
);

// =====================================
// Month Rows
// =====================================

const latest = parseDate(latestDate);

const monthRows = rows.filter(r => {

    const d = parseDate(r.date);

    return d &&
        d.getMonth() === latest.getMonth() &&
        d.getFullYear() === latest.getFullYear();

});

// =====================================
// Helper
// =====================================

function sum(arr,key){

    return arr.reduce(
        (total,row)=>total+Number(row[key]||0),
        0
    );

}

// =====================================
// Yesterday Totals
// =====================================

const yesterdayNet = sum(yesterdayRows,"net_sale");

const yesterdayGross = sum(yesterdayRows,"gross_sale");

const yesterdayQty = sum(yesterdayRows,"qty_sold");

// =====================================
// Yesterday Category
// =====================================


const heritageRows = yesterdayRows.filter(
    r => r.category === "Heritage Collection"
);

const urbanRows = yesterdayRows.filter(
    r => r.category === "Urban Collection"
);

const heritageNet = sum(heritageRows, "net_sale");

const urbanNet = sum(urbanRows, "net_sale");

const heritageQty = sum(heritageRows, "qty_sold");

const urbanQty = sum(urbanRows, "qty_sold");
// =====================================
// Month Totals
// =====================================

const monthNet = sum(monthRows,"net_sale");

const monthGross = sum(monthRows,"gross_sale");

const monthQty = sum(monthRows,"qty_sold");

// =====================================
// Brand Statistics
// =====================================

const brandStats = {};

monthRows.forEach(r=>{

    if(!brandStats[r.brands]){

        brandStats[r.brands]={
            brand:r.brands,
            monthQty:0,
            monthNet:0,
            yesterdayQty:0,
            yesterdayNet:0
        };

    }

    brandStats[r.brands].monthQty += r.qty_sold;

    brandStats[r.brands].monthNet += r.net_sale;

});

yesterdayRows.forEach(r=>{

    if(!brandStats[r.brands]) return;

    brandStats[r.brands].yesterdayQty += r.qty_sold;

    brandStats[r.brands].yesterdayNet += r.net_sale;

});

const sortedBrands = Object.values(brandStats)
.sort((a,b)=>b.monthNet-a.monthNet);

// =====================================
// Yesterday Top Brand
// =====================================

const topYesterdayBrand = sortedBrands
.slice()
.sort((a,b)=>b.yesterdayNet-a.yesterdayNet)[0];

// =====================================
// Month Category
// =====================================


const monthHeritage = sum(
    monthRows.filter(r => r.category === "Heritage Collection"),
    "net_sale"
);

const monthUrban = sum(
    monthRows.filter(r => r.category === "Urban Collection"),
    "net_sale"
);

const monthHeritageQty = sum(
    monthRows.filter(r => r.category === "Heritage Collection"),
    "qty_sold"
);

const monthUrbanQty = sum(
    monthRows.filter(r => r.category === "Urban Collection"),
    "qty_sold"
);

// =====================================
// Output
// =====================================

return [{
json:{

reportDate:latestDate,

yesterdayNet,

yesterdayGross,

yesterdayQty,

heritageNet,

urbanNet,

heritageQty,

urbanQty,

monthNet,

monthGross,

monthQty,

monthHeritage,

monthUrban,

monthHeritageQty,

monthUrbanQty,

topYesterdayBrand,

top3Brands:sortedBrands.slice(0,3),

brandSales:sortedBrands

}
}];
